 def contactcta():
  title,text,cta=CONTACT_COPY[lang].get(page,(d['contacttitle'],d['contacttext'],d['cta']))
  return '<section class="contact-banner"><div><span class="eyebrow">'+d['contactlabel']+'</span><h2>'+title+'</h2></div><div><p>'+text+'</p>'+button(cta,url(lang,'contact'))+'</div></section>'
